3:# Safe to run any number of times: every step checks first and only installs / merges what is missing.
7:#   bash scripts/claude-bootstrap.sh --check    report only: no installs, no merges (fetch is still done)
11:#   options: --no-tools (skip Blender/Android/pip/plugin installs)  --skip-resume (no merge; the DEFAULT since
12:#            2026-11-17)  --resume (merge newer ccr-*/claude/* branches — only with the user's explicit OK)
18:# Safety: never force-pushes, resets, rebases, deletes files or rewrites history. Merges are normal merge commits;
19:# a merge that conflicts (outside auto-generated status files) is ABORTED and reported, never left half-done.
24:MODE=full; DO_RESUME=0;   # 2026-11-17 (user): NO automatic merges; --resume opts in, only with the user's OK
35:  --skip-resume) DO_RESUME=0 ;;
36:  --resume) DO_RESUME=1 ;;   # merge newer ccr-*/claude/* branches: ONLY after the user authorised it
111:merge_one() {  # ref -> 0 merged | 1 conflict (aborted) | 2 refused
113:  if git merge --no-edit -q -m "resume: merge newer saved work from ${ref#origin/}" "$ref" >/dev/null 2>&1; then return 0; fi
115:    git -c commit.gpgsign=false merge --no-edit -q -m "resume: merge newer saved work from ${ref#origin/}" "$ref" >/dev/null 2>&1 && return 0
123:      git merge-file --union "$tmpd/o" "$tmpd/b" "$tmpd/t"; cp "$tmpd/o" "$f"; git add -- "$f"
129:    git merge --abort; return 1
132:  git merge --abort 2>/dev/null; return 2
136:  local t merged="" conflicts="" refused="" total=0 contained=0 dirty ref; t=$(now)
144:    for busy in MERGE_HEAD rebase-merge rebase-apply CHERRY_PICK_HEAD; do
148:    if [ "$dirty" != 0 ]; then   # save the current edits first, so a merge can never touch unsaved work
149:      timeout 600 python3 "$ROOT/scripts/rainbow-autosave.py" --reason bootstrap:pre-merge --quiet >/dev/null 2>&1
156:        git merge-base --is-ancestor "$ref" HEAD 2>/dev/null && continue
159:        merge_one "$ref"; case $? in
160:          0) merged="$merged ${ref#origin/}" ;;
171:    total=$((total + 1)); git merge-base --is-ancestor "$ref" HEAD 2>/dev/null && contained=$((contained + 1))
175:  [ -n "$merged" ] && msg="$msg; merged newer work from:$merged"
177:    rec resume "Resume newest work" fail "$msg; CONFLICT (merge aborted, nothing changed):$conflicts - merge by hand keeping both sides: git merge origin/<branch>" "$t"
179:    rec resume "Resume newest work" fail "$msg; merge refused for:$refused (see git status)" "$t"
181:    rec resume "Resume newest work" warn "$msg; not merged ($([ "$DO_RESUME" = 1 ] && echo 'unsaved edits or busy lock' || echo 'automatic merge disabled (use --resume only with the user'\''s OK)')): run bash scripts/claude-bootstrap.sh" "$t"
412:  if [ "${CLAUDE_CODE_REMOTE:-}" != true ]; then   # local machine: no automatic merges or installs
462:    echo "      the merge brought a newer claude-bootstrap.sh: continuing with it"
467:# after the merge, so an old checkout already has scripts/verify-assets.py (the hook ran this itself)
---
{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          { "type": "command", "command": "bash \"$CLAUDE_PROJECT_DIR/scripts/autosave-hook.sh\" SessionStart", "timeout": 600 }
        ]
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          { "type": "command", "command": "bash \"$CLAUDE_PROJECT_DIR/scripts/autosave-hook.sh\" PreCompact", "timeout": 120 }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          { "type": "command", "command": "bash \"$CLAUDE_PROJECT_DIR/scripts/autosave-hook.sh\" Stop", "timeout": 30 }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          { "type": "command", "command": "bash \"$CLAUDE_PROJECT_DIR/scripts/autosave-hook.sh\" SessionEnd", "timeout": 120 }
        ]
      }
    ]
  }
}
---
3:# SessionStart -> scripts/claude-bootstrap.sh --hook: merges newer saved work, restores Git LFS, re-arms the
4:#   five-minute autosave, prints a short recovery summary for Claude and runs the full bootstrap in the background.
11:    if [ -f "$REPO/scripts/claude-bootstrap.sh" ]; then
12:      exec bash "$REPO/scripts/claude-bootstrap.sh" --hook     # reads the hook JSON (source) from stdin
14:    # fallback for an old checkout without the bootstrap

