1	#!/usr/bin/env node
2	import { copyFile, readFile, readdir } from "node:fs/promises";
3	import path from "node:path";
4	import {
5	  downloadFile,
6	  ensureDir,
7	  inferMime,
8	  isUrl,
9	  many,
10	  one,
11	  parseArgs,
12	  pathExists,
13	  readJson,
14	  requireEnv,
15	  stripBase64,
16	  writeJson
17	} from "../asset-pipeline/fal-queue.mjs";
18	import {
19	  artifactPath,
20	  isVisibleFile,
21	  nextIndex,
22	  parseIndexedName,
23	  requestPath
24	} from "../asset-pipeline/request-metadata.mjs";
25	
26	const ENDPOINT = "https://api.worldlabs.ai/marble/v1";
27	const MODEL = "marble-1.1";
28	const IMAGE_EXTENSIONS = new Set([".avif", ".gif", ".heic", ".heif", ".jpeg", ".jpg", ".png", ".webp"]);
29	
30	async function downloadAsset(url, destPath) {
31	  if (await pathExists(destPath)) return destPath;
32	  return downloadFile(url, destPath);
33	}
34	
35	async function copyWorldPlate(image, outputDir, index) {
36	  if (!image || isUrl(image)) return undefined;
37	  const ext = path.extname(image).toLowerCase();
38	  if (!IMAGE_EXTENSIONS.has(ext)) return undefined;
39	
40	  const sourcePath = path.resolve(image);
41	  if (!(await pathExists(sourcePath))) return undefined;
42	
43	  const destPath = artifactPath(outputDir, index, "world-plate", ext);
44	  if (!(await pathExists(destPath))) await copyFile(sourcePath, destPath);
45	  return destPath;
46	}
47	
48	function extensionFromUrl(url, fallback) {
49	  try {
50	    return path.extname(new URL(url).pathname) || fallback;
51	  } catch {
52	    return fallback;
53	  }
54	}
55	
56	function assetKeyForFilename(key) {
57	  return String(key).replace(/[^a-z0-9_-]/gi, "_");
58	}
59	
60	async function downloadWorldAssets(worldResponse, outputDir, index) {
61	  const assets = worldResponse.assets || {};
62	  const result = { spz: {} };
63	
64	  const glbUrl = assets.mesh?.collider_mesh_url;
65	  if (glbUrl) {
66	    result.glb = await downloadAsset(glbUrl, path.join(outputDir, `${index}-world.glb`));
67	  }
68	
69	  const panoUrl = assets.imagery?.pano_url;
70	  if (panoUrl) {
71	    const ext = extensionFromUrl(panoUrl, ".png");
72	    result.pano = await downloadAsset(panoUrl, path.join(outputDir, `${index}-world-pano${ext}`));
73	  }
74	
75	  const thumbnailUrl = assets.thumbnail_url;
76	  if (thumbnailUrl) {
77	    const ext = extensionFromUrl(thumbnailUrl, ".webp");
78	    result.thumbnail = await downloadAsset(thumbnailUrl, path.join(outputDir, `${index}-world-thumbnail${ext}`));
79	  }
80	
81	  const spzUrls = assets.splats?.spz_urls || {};
82	  for (const [key, url] of Object.entries(spzUrls)) {
83	    if (!url) continue;
84	    result.spz[key] = await downloadAsset(url, path.join(outputDir, `${index}-world-${assetKeyForFilename(key)}.spz`));
85	  }
86	
87	  return result;
88	}
89	
90	function sleep(ms) {
91	  return new Promise((resolve) => setTimeout(resolve, ms));
92	}
93	
94	async function readJsonIfExists(filePath) {
95	  return (await pathExists(filePath)) ? readJson(filePath) : undefined;
96	}
97	
98	async function latestSourceImage(sourceDir) {
99	  const entries = await readdir(sourceDir, { withFileTypes: true }).catch(() => []);
100	  const images = entries
101	    .filter((entry) => entry.isFile())
102	    .map((entry) => path.join(sourceDir, entry.name))
103	    .filter((filePath) => isVisibleFile(filePath) && IMAGE_EXTENSIONS.has(path.extname(filePath).toLowerCase()))
104	    .map((filePath) => parseIndexedName(filePath) || { index: 0, path: filePath, slug: path.basename(filePath) });
105	
106	  return images.sort((a, b) => b.index - a.index || a.slug.localeCompare(b.slug))[0]?.path;
107	}
108	
109	async function promptFromImageJson(world) {
110	  const imageJson = await readJsonIfExists(`worlds/${world}/image.json`);
111	  if (!imageJson) return undefined;
